#!/usr/bin/env bash
# From system/: copy/source COMMANDS into run_now.sh; this file never starts jobs.
# Use a new tag for each run. The K3 pair shares ONLY this SVD first-round grouping file.
SVD_RUN_TAG="${SVD_RUN_TAG:-$(date +%Y%m%d_%H%M%S)}"
SVD_DATA_ROOT="${SVD_DATA_ROOT:-../dataset}"
SVD_RUN_ROOT="${SVD_RUN_ROOT:-multi_svd_runs/$SVD_RUN_TAG}"
SVD_GROUP_FILE="${SVD_GROUP_FILE:-$SVD_RUN_ROOT/shared/svd_K3_first_full_weights.json}"
SVD_GROUP_WAIT="${SVD_GROUP_WAIT:-7200}"
declare -a COMMANDS=(
"python -u main.py -algo FedMultiGroupProj -data Cifar100 -m Decom_CNN-5-512 -dev cuda -did 0 -nc 20 -ncl 100 -nsm 1 --seed 0 -t 1 -pv 0 -jr 1.0 -lr 0.005 -lbs 16 -ls 5 -gr 100 -eg 1 -is_regular 1 -regular_lamda 1e-3 --target_prox_mu 0 --target_head_l2_lambda 0 --target_head_mode shared --target_local_schedule joint --control_eval_scope all --local_grad_clip 10 --control_test_batch_size 16 -clip_cpu_threads 4 -niid 1 -pt pat -cpc 20 --data-root '$SVD_DATA_ROOT' --data-subdir pat_20 --data-formats npz_only --data-expected-partition pat --multi_svd --multi_svd_ratios 0.9,0.37,0.35,0.25,0.15 --multi_svd_diagnostics 1 --multi_warmup_rounds 0 --multi_group_basis full_weights --multi_group_sizes 20 --multi_group_mode group_avg_only --multi_group_weight 1.0 --group_softmax_tau 0.20 --multi_cluster_seed 0 --multi_cluster_restarts 8 --multi_cluster_iterations 50  -exp_name svd_K1_avg_all_seed0_gr100 -sfn '$SVD_RUN_ROOT/svd_K1_avg_all/checkpoints' --run_log_dir '$SVD_RUN_ROOT/svd_K1_avg_all/logs' --h5_result_root '$SVD_RUN_ROOT/svd_K1_avg_all/h5' --final_model_root '$SVD_RUN_ROOT/svd_K1_avg_all/final_models'"
"python -u main.py -algo FedMultiGroupProj -data Cifar100 -m Decom_CNN-5-512 -dev cuda -did 1 -nc 20 -ncl 100 -nsm 3 --seed 0 -t 1 -pv 0 -jr 1.0 -lr 0.005 -lbs 16 -ls 5 -gr 100 -eg 1 -is_regular 1 -regular_lamda 1e-3 --target_prox_mu 0 --target_head_l2_lambda 0 --target_head_mode shared --target_local_schedule joint --control_eval_scope all --local_grad_clip 10 --control_test_batch_size 16 -clip_cpu_threads 4 -niid 1 -pt pat -cpc 20 --data-root '$SVD_DATA_ROOT' --data-subdir pat_20 --data-formats npz_only --data-expected-partition pat --multi_svd --multi_svd_ratios 0.9,0.37,0.35,0.25,0.15 --multi_svd_diagnostics 1 --multi_warmup_rounds 0 --multi_group_basis full_weights --multi_group_sizes 7,7,6 --multi_group_mode group_avg_only --multi_group_weight 0.50 --group_softmax_tau 0.20 --multi_cluster_seed 0 --multi_cluster_restarts 8 --multi_cluster_iterations 50 --multi_group_file '$SVD_GROUP_FILE' --multi_group_wait_seconds $SVD_GROUP_WAIT --multi_group_poll_seconds 1 -exp_name svd_K3_group_avg_only_seed0_gr100 -sfn '$SVD_RUN_ROOT/svd_K3_group_avg_only/checkpoints' --run_log_dir '$SVD_RUN_ROOT/svd_K3_group_avg_only/logs' --h5_result_root '$SVD_RUN_ROOT/svd_K3_group_avg_only/h5' --final_model_root '$SVD_RUN_ROOT/svd_K3_group_avg_only/final_models'"
"python -u main.py -algo FedMultiGroupProj -data Cifar100 -m Decom_CNN-5-512 -dev cuda -did 2 -nc 20 -ncl 100 -nsm 3 --seed 0 -t 1 -pv 0 -jr 1.0 -lr 0.005 -lbs 16 -ls 5 -gr 100 -eg 1 -is_regular 1 -regular_lamda 1e-3 --target_prox_mu 0 --target_head_l2_lambda 0 --target_head_mode shared --target_local_schedule joint --control_eval_scope all --local_grad_clip 10 --control_test_batch_size 16 -clip_cpu_threads 4 -niid 1 -pt pat -cpc 20 --data-root '$SVD_DATA_ROOT' --data-subdir pat_20 --data-formats npz_only --data-expected-partition pat --multi_svd --multi_svd_ratios 0.9,0.37,0.35,0.25,0.15 --multi_svd_diagnostics 1 --multi_warmup_rounds 0 --multi_group_basis full_weights --multi_group_sizes 7,7,6 --multi_group_mode group_projection_softmax --multi_group_weight 0.50 --group_softmax_tau 0.20 --multi_cluster_seed 0 --multi_cluster_restarts 8 --multi_cluster_iterations 50 --multi_group_publish '$SVD_GROUP_FILE' -exp_name svd_K3_group_projection_softmax_seed0_gr100 -sfn '$SVD_RUN_ROOT/svd_K3_group_projection_softmax/checkpoints' --run_log_dir '$SVD_RUN_ROOT/svd_K3_group_projection_softmax/logs' --h5_result_root '$SVD_RUN_ROOT/svd_K3_group_projection_softmax/h5' --final_model_root '$SVD_RUN_ROOT/svd_K3_group_projection_softmax/final_models'"
)
